-- Explicações por artigo — Lei Henry Borel (Lei nº 14.344, de 2022). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei cria mecanismos para a prevenção e o enfrentamento da violência doméstica e familiar contra a criança e o adolescente, nos termos da Constituição e dos tratados internacionais ratificados pelo Brasil, e altera o Código Penal, a Lei de Execução Penal, o Estatuto da Criança e do Adolescente, a Lei dos Crimes Hediondos e a Lei que estabelece o sistema de garantia de direitos da criança e do adolescente vítima ou testemunha de violência.', '["Prevenção e enfrentamento da violência doméstica e familiar contra criança e adolescente.","Fundamento constitucional e em tratados internacionais.","Altera o Código Penal, a LEP, o ECA, a Lei dos Crimes Hediondos e a Lei nº 13.431."]'::jsonb, '["Funciona como uma ''Lei Maria da Penha'' das crianças e adolescentes.","Tem aplicação subsidiária do ECA, da Lei Maria da Penha e da Lei nº 13.431 (art. 33)."]'::jsonb, 'A criança agredida em casa recebe medidas protetivas de urgência com base nesta Lei.', '["Assertiva que restringe a Lei à proteção de mulheres erra: ela trata de crianças e adolescentes."]'::jsonb, '[]'::jsonb, '["Lei Maria da Penha","Estatuto da Criança e do Adolescente"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Configura violência doméstica e familiar contra a criança e o adolescente qualquer ação ou omissão que lhe cause morte, lesão, sofrimento físico, sexual, psicológico ou dano patrimonial, no âmbito do domicílio ou residência (espaço de convívio permanente, com ou sem vínculo familiar), no âmbito da família (natural, ampliada ou substituta) e em qualquer relação doméstica e familiar na qual o agressor conviva ou tenha convivido com a vítima, independentemente de coabitação. Para a caracterização, observam-se as definições da Lei nº 13.431, de 4 de abril de 2017.', '["Ação ou omissão que cause morte, lesão, sofrimento ou dano patrimonial.","Âmbitos: domicílio, família e relações domésticas e familiares.","Independe de coabitação.","Definições da Lei nº 13.431."]'::jsonb, '["Abrange a OMISSÃO e o dano PATRIMONIAL.","Não exige coabitação."]'::jsonb, 'O padrasto que agride o enteado pratica violência doméstica e familiar.', '["Assertiva que exige coabitação para configurar a violência doméstica erra."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A violência doméstica e familiar contra a criança e o adolescente constitui uma das formas de violação dos direitos humanos.', '["Violência doméstica contra criança e adolescente é violação de direitos humanos."]'::jsonb, '["Reafirma a natureza de violação de direitos humanos."]'::jsonb, 'A agressão contra a criança em casa é uma violação de direitos humanos.', '["Assertiva que trata a violência doméstica como assunto exclusivamente privado erra."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As estatísticas sobre a violência doméstica e familiar contra a criança e o adolescente serão incluídas nas bases de dados dos órgãos oficiais do Sistema de Garantia dos Direitos da Criança e do Adolescente, do SUS, do SUAS e do Sistema de Justiça e Segurança, de forma integrada. Os entes federados poderão remeter suas informações às bases do Ministério da Justiça e Segurança Pública e do Ministério da Mulher, da Família e dos Direitos Humanos. Os serviços compartilharão as informações coletadas de forma integrada, preservado o sigilo, por meio de relatórios. O compartilhamento completo será feito por encaminhamento ao serviço do sistema de garantia de direitos, que acolherá a criança ou o adolescente. Será adotado modelo de registro com dados pessoais, descrição do atendimento, relato espontâneo e encaminhamentos efetuados.', '["Estatísticas integradas entre o sistema de garantia, SUS, SUAS e justiça e segurança.","Compartilhamento sigiloso de informações.","Modelo de registro com dados pessoais, atendimento, relato e encaminhamentos."]'::jsonb, '["Sigilo dos dados da criança ou do adolescente."]'::jsonb, 'O serviço de saúde e o Conselho Tutelar compartilham, com sigilo, as informações do atendimento.', '["Assertiva que dispensa o sigilo no compartilhamento dos dados erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Sistema de Garantia dos Direitos da Criança e do Adolescente intervirá nas situações de violência com a finalidade de mapear as ocorrências e suas particularidades; prevenir os atos de violência; fazer cessar a violência quando ocorrer; prevenir a reiteração; promover o atendimento para minimizar as sequelas; promover a reparação integral dos direitos; e promover a parentalidade positiva e o direito ao brincar como estratégias de prevenção.', '["Mapear, prevenir, fazer cessar e evitar a reiteração.","Atendimento para minimizar sequelas e reparação integral.","Parentalidade positiva e direito ao brincar."]'::jsonb, '["ATUALIZAÇÃO: o inciso VII (parentalidade positiva e direito ao brincar) foi incluído por lei posterior."]'::jsonb, 'O sistema atua para interromper a violência e evitar que ela se repita.', '["Assertiva que restringe a atuação do sistema à punição do agressor erra."]'::jsonb, '[{"termo":"Parentalidade positiva","significado":"Educação dos filhos sem violência, com afeto e limites."}]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A assistência à criança e ao adolescente em situação de violência doméstica e familiar será prestada de forma articulada e conforme os princípios e as diretrizes do Estatuto da Criança e do Adolescente, da Lei Orgânica da Assistência Social, do Sistema Único de Saúde, do Sistema Único de Segurança Pública, entre outras normas e políticas públicas, e emergencialmente, quando for o caso.', '["Assistência articulada entre ECA, assistência social, SUS e segurança pública.","Atendimento emergencial quando necessário."]'::jsonb, '["Atuação em REDE, e não isolada."]'::jsonb, 'Saúde, assistência social e polícia atuam em conjunto no atendimento da criança.', '["Assertiva que atribui a assistência a um único órgão erra: é articulada."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A União, o Distrito Federal, os Estados e os Municípios poderão criar e promover, no limite das respectivas competências, centros de atendimento integral e multidisciplinar; espaços para acolhimento familiar e institucional e programas de apadrinhamento; delegacias, núcleos de defensoria pública, serviços de saúde e centros de perícia médico-legal especializados; programas e campanhas de enfrentamento; e centros de educação e de reabilitação para os agressores.', '["Centros de atendimento integral e multidisciplinar.","Acolhimento familiar e institucional e apadrinhamento.","Delegacias, defensoria, saúde e perícia especializados.","Centros de reabilitação para agressores."]'::jsonb, '["Faculdade (''poderão'') dos entes federativos."]'::jsonb, 'O Estado cria um centro de atendimento multidisciplinar para crianças vítimas de violência.', '["Assertiva que torna obrigatória a criação desses serviços pelos entes erra: é faculdade."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

