insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O depoimento da criança e do adolescente vítima ou testemunha de violência doméstica e familiar será colhido nos termos da Lei nº 13.431, de 4 de abril de 2017, observadas as disposições do Estatuto da Criança e do Adolescente.', '["Depoimento colhido conforme a Lei nº 13.431.","Observância do ECA."]'::jsonb, '["Depoimento especial e escuta especializada seguem a Lei nº 13.431."]'::jsonb, 'A criança é ouvida em depoimento especial, sem exposição ao agressor.', '["Assertiva que prevê a oitiva da criança como em qualquer testemunha adulta erra: segue a Lei nº 13.431."]'::jsonb, '[{"termo":"Depoimento especial","significado":"Oitiva protegida da criança ou do adolescente vítima ou testemunha."}]'::jsonb, '["Lei nº 13.431"]'::jsonb, 'under_review', 'claude'
