on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No atendimento à criança e ao adolescente em situação de violência doméstica e familiar, a autoridade policial deverá, entre outras providências, encaminhar a vítima ao SUS e ao Instituto Médico-Legal imediatamente; encaminhar a vítima, os familiares e as testemunhas crianças ou adolescentes ao Conselho Tutelar; garantir proteção policial quando necessário, comunicando de imediato o Ministério Público e o Poder Judiciário; e fornecer transporte para a vítima e, quando necessário, para seu responsável ou acompanhante, para serviço de acolhimento ou local seguro, quando houver risco à vida.', '["Encaminhamento ao SUS e ao IML.","Encaminhamento ao Conselho Tutelar.","Proteção policial, com comunicação ao MP e ao Judiciário.","Transporte para acolhimento ou local seguro."]'::jsonb, '["Transporte da vítima quando houver risco à vida."]'::jsonb, 'A autoridade policial leva a criança ferida ao hospital e comunica o Conselho Tutelar.', '["Assertiva que dispensa a comunicação ao Ministério Público erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificada a ocorrência de ação ou omissão que implique a ameaça ou a prática de violência doméstica e familiar, com risco atual ou iminente à vida ou à integridade física da criança e do adolescente ou de seus familiares, o agressor será imediatamente afastado do lar, domicílio ou local de convivência: pela autoridade judicial; pelo delegado de polícia, quando o Município não for sede de comarca; ou pelo policial, quando não for sede de comarca e não houver delegado disponível. O Conselho Tutelar poderá representar para requerer o afastamento. Nos casos dos incisos II e III, o juiz será comunicado em 24 horas e decidirá em igual prazo sobre a manutenção ou revogação. Havendo risco à integridade física da vítima ou à efetividade da medida, não se concede liberdade provisória ao preso.', '["Afastamento imediato do agressor em caso de risco.","Quem pode afastar: juiz, delegado (Município sem comarca) ou policial (sem delegado disponível).","Comunicação ao juiz em 24 horas, que decide em igual prazo.","Conselho Tutelar pode representar.","Sem liberdade provisória em risco à vítima."]'::jsonb, '["Afastamento em localidades sem comarca pode ser feito por delegado ou policial, com controle judicial em 24 horas."]'::jsonb, 'Em cidade sem juiz, o policial afasta o agressor e o juiz é comunicado em 24 horas.', '["Assertiva que reserva o afastamento sempre ao juiz erra: delegado e policial podem fazê-lo em Município sem comarca."]'::jsonb, '[]'::jsonb, '["Lei Maria da Penha"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Recebido o expediente com o pedido em favor de criança e de adolescente em situação de violência doméstica e familiar, caberá ao juiz, em 24 horas, conhecer do pedido e decidir sobre as medidas protetivas de urgência; determinar o encaminhamento do responsável ao órgão de assistência judiciária, quando for o caso; comunicar ao Ministério Público; e determinar a apreensão imediata de arma de fogo sob a posse do agressor.', '["Prazo de 24 horas para o juiz.","Decide sobre as medidas protetivas.","Encaminha o responsável à assistência judiciária.","Comunica ao MP e manda apreender arma de fogo."]'::jsonb, '["Prazo de 24 horas para decidir as protetivas."]'::jsonb, 'Em 24 horas o juiz decide as medidas e manda apreender a arma do agressor.', '["Assertiva que fixa em dois dias o prazo do juiz erra: são vinte e quatro horas."]'::jsonb, '[]'::jsonb, '["Art. 16","Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As medidas protetivas de urgência poderão ser concedidas pelo juiz a requerimento do Ministério Público, da autoridade policial, do Conselho Tutelar ou a pedido da pessoa que atue em favor da criança e do adolescente. Poderão ser concedidas de imediato, independentemente de audiência das partes e de manifestação do Ministério Público, que será prontamente comunicado. Serão aplicadas isolada ou cumulativamente e poderão ser substituídas a qualquer tempo por outras de maior eficácia. O juiz poderá, a requerimento ou a pedido, conceder novas medidas ou rever as já concedidas, ouvido o Ministério Público.', '["Requerimento do MP, da autoridade policial, do Conselho Tutelar ou de quem atue em favor da vítima.","Concessão imediata, sem audiência prévia.","Aplicação isolada ou cumulativa.","Substituição por medidas de maior eficácia."]'::jsonb, '["Não depende de audiência das partes nem de manifestação prévia do MP."]'::jsonb, 'O juiz concede a protetiva logo, sem ouvir o agressor, e comunica o MP.', '["Assertiva que condiciona a medida protetiva à audiência prévia das partes erra."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em qualquer fase do inquérito policial ou da instrução criminal, caberá a prisão preventiva do agressor, decretada pelo juiz, a requerimento do Ministério Público ou por representação da autoridade policial. O juiz poderá revogá-la se verificar a falta de motivo para que subsista, bem como decretá-la novamente, se sobrevierem razões que a justifiquem.', '["Prisão preventiva em qualquer fase do inquérito ou da instrução.","Decretada pelo juiz, a pedido do MP ou por representação da autoridade policial.","Pode ser revogada e novamente decretada."]'::jsonb, '["O juiz não decreta a preventiva sem provocação nesta Lei (requerimento ou representação)."]'::jsonb, 'A autoridade policial representa pela preventiva do agressor que ameaça a criança.', '["Assertiva que impede a nova decretação da preventiva após a revogação erra."]'::jsonb, '[]'::jsonb, '["Código de Processo Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O responsável legal pela criança ou pelo adolescente vítima ou testemunha de violência doméstica e familiar, desde que não seja o autor das agressões, deverá ser notificado dos atos processuais relativos ao agressor, especialmente dos pertinentes ao ingresso e à saída da prisão, sem prejuízo da intimação do advogado constituído ou do defensor público.', '["Notificação do responsável legal dos atos processuais.","Especialmente entrada e saída da prisão.","Não vale se o responsável for o agressor."]'::jsonb, '["Notificação NÃO substitui a intimação do advogado ou defensor."]'::jsonb, 'A mãe da criança é avisada de que o agressor será solto.', '["Assertiva que notifica o próprio agressor como responsável legal erra: a regra exclui o autor das agressões."]'::jsonb, '[]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-18'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz competente providenciará o registro da medida protetiva de urgência. As medidas serão, após a concessão, imediatamente registradas em banco de dados mantido e regulamentado pelo Conselho Nacional de Justiça, garantido o acesso instantâneo do Ministério Público, da Defensoria Pública, dos órgãos de segurança pública e de assistência social e dos integrantes do Sistema de Garantia dos Direitos da Criança e do Adolescente.', '["Registro da medida protetiva.","Banco de dados mantido pelo CNJ.","Acesso instantâneo do MP, Defensoria, segurança e assistência."]'::jsonb, '["O banco é do CNJ."]'::jsonb, 'A medida concedida aparece no banco do CNJ e a polícia pode consultá-la na hora.', '["Assertiva que atribui o banco de protetivas ao Ministério Público erra: é do CNJ."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constatada a violência, o juiz poderá determinar ao agressor, de imediato, em conjunto ou separadamente, medidas protetivas de urgência como a suspensão da posse ou restrição do porte de armas; o afastamento do lar; a proibição de aproximação da vítima, de seus familiares, das testemunhas e dos denunciantes, com limite mínimo de distância; a vedação de contato por qualquer meio; a proibição de frequentar determinados lugares; a restrição ou suspensão de visitas; a prestação de alimentos provisionais ou provisórios; o comparecimento a programas de recuperação e reeducação; e o acompanhamento psicossocial. As medidas não impedem outras previstas em lei, e todas devem ser comunicadas ao Ministério Público. Quando o agressor for autorizado a portar arma por função, o juiz comunica o órgão e o superior imediato é responsável pelo cumprimento, sob pena de prevaricação ou desobediência. O juiz pode requisitar auxílio da força policial a qualquer momento.', '["Rol exemplificativo de medidas protetivas contra o agressor.","Suspensão da posse ou restrição do porte de armas.","Afastamento do lar, proibição de aproximação e de contato.","Alimentos provisionais e programas de reeducação.","Superior do agressor armado responde pelo cumprimento."]'::jsonb, '["Rol não taxativo (''entre outras'').","O superior hierárquico do agressor armado responde se não cumprir a ordem."]'::jsonb, 'O juiz afasta o agressor do lar e suspende o seu porte de arma.', '["Assertiva que considera taxativo o rol de medidas do art. 20 erra: a lei diz ''entre outras''."]'::jsonb, '[]'::jsonb, '["Art. 21","Estatuto do Desarmamento"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-20'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poderá o juiz, quando necessário, sem prejuízo de outras medidas, determinar a proibição de contato entre a criança vítima ou testemunha e o agressor; o afastamento do agressor da residência; a prisão preventiva quando houver suficientes indícios de ameaça; a inclusão da vítima e de sua família nos atendimentos da assistência social; a inclusão em programa de proteção a vítimas ou testemunhas; a remessa do caso ao juízo competente para avaliar acolhimento familiar, institucional ou família substituta, se não for possível afastar ou prender o agressor; e a matrícula da criança na instituição de educação mais próxima, independentemente de vaga. A autoridade policial pode requisitar e o Conselho Tutelar requerer ao MP a ação cautelar de antecipação de prova.', '["Proibição de contato e afastamento do agressor.","Prisão preventiva em caso de ameaça.","Inclusão em programa de proteção.","Acolhimento ou família substituta se não houver afastamento.","Matrícula em escola próxima, independentemente de vaga.","Ação cautelar de antecipação de prova."]'::jsonb, '["Matrícula garantida mesmo sem vaga."]'::jsonb, 'A criança é matriculada em escola próxima à nova moradia, mesmo sem vaga.', '["Assertiva que condiciona a matrícula à existência de vaga erra."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá ao Ministério Público, sem prejuízo de outras atribuições, nos casos de violência doméstica e familiar contra a criança e o adolescente, quando necessário, registrar em seu sistema de dados os casos; requisitar força policial e serviços públicos de saúde, educação, assistência social e segurança; e fiscalizar os estabelecimentos públicos e particulares de atendimento, adotando de imediato as medidas administrativas ou judiciais cabíveis.', '["Registro dos casos em sistema de dados.","Requisição de força policial e serviços públicos.","Fiscalização de estabelecimentos de atendimento."]'::jsonb, '["Rol de atribuições sem prejuízo de outras."]'::jsonb, 'O Promotor fiscaliza o abrigo e adota medidas diante de irregularidades.', '["Assertiva que retira do Ministério Público a fiscalização dos estabelecimentos de atendimento erra."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Qualquer pessoa que tenha conhecimento ou presencie ação ou omissão, em local público ou privado, que constitua violência doméstica e familiar contra a criança e o adolescente tem o dever de comunicar o fato imediatamente ao serviço de recebimento e monitoramento de denúncias, ao Disque 100, ao Conselho Tutelar ou à autoridade policial, que tomarão as providências cabíveis.', '["Dever de qualquer pessoa de comunicar.","Canais: serviço de denúncias, Disque 100, Conselho Tutelar ou polícia."]'::jsonb, '["O dever é de QUALQUER pessoa.","O descumprimento pode configurar o crime do art. 26."]'::jsonb, 'O vizinho que ouve agressões contra a criança liga para o Disque 100.', '["Assertiva que restringe o dever de comunicar a profissionais da saúde erra: é de qualquer pessoa."]'::jsonb, '[{"termo":"Disque 100","significado":"Canal nacional de denúncias de violações de direitos humanos."}]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público garantirá meios e estabelecerá medidas e ações para a proteção e a compensação da pessoa que noticiar informações ou denunciar a prática de violência, de tratamento cruel ou degradante ou de formas violentas de educação, correção ou disciplina contra a criança e o adolescente. Os entes poderão estabelecer programas de proteção e compensação. O noticiante poderá requerer que a revelação seja feita perante a polícia, o Conselho Tutelar, o MP ou o juiz, e poderá condicionar a revelação à execução de medidas de proteção. Ninguém será submetido a retaliação por ter reportado a violência. O denunciante coagido ou ameaçado poderá requerer as medidas da Lei de Proteção a Vítimas e Testemunhas. O MP se manifestará sobre a necessidade e utilidade das medidas.', '["Proteção e compensação de quem denuncia a violência.","Revelação perante a polícia, o Conselho Tutelar, o MP ou o juiz.","Vedada a retaliação.","Medidas da Lei de Proteção a Vítimas e Testemunhas em caso de ameaça."]'::jsonb, '["Proteção do denunciante contra retaliação."]'::jsonb, 'O denunciante ameaçado pede inclusão em programa de proteção.', '["Assertiva que permite punir o denunciante pela revelação erra: ele é protegido contra retaliação."]'::jsonb, '[]'::jsonb, '["Lei de Proteção a Vítimas e Testemunhas"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Descumprir decisão judicial que defere medida protetiva de urgência prevista nesta Lei: detenção de três meses a dois anos. A configuração do crime independe da competência civil ou criminal do juiz que deferiu a medida. Na prisão em flagrante, apenas a autoridade judicial poderá conceder fiança. O disposto não exclui a aplicação de outras sanções cabíveis.', '["Descumprimento de medida protetiva: detenção de três meses a dois anos.","Independe da competência civil ou criminal do juiz que deferiu.","Fiança só pela autoridade judicial.","Não exclui outras sanções."]'::jsonb, '["Só o JUIZ pode arbitrar fiança neste crime.","Pena de DETENÇÃO."]'::jsonb, 'O agressor que se aproxima da criança, descumprindo a protetiva, comete o crime do art. 25.', '["Assertiva que permite ao delegado conceder fiança no descumprimento de medida protetiva erra: só o juiz."]'::jsonb, '[]'::jsonb, '["Lei Maria da Penha, art. 24-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de comunicar à autoridade pública a prática de violência, de tratamento cruel ou degradante ou de formas violentas de educação, correção ou disciplina contra criança ou adolescente, ou o abandono de incapaz: detenção de seis meses a três anos. A pena é aumentada de metade se da omissão resulta lesão corporal de natureza grave, e triplicada se resulta morte. Aplica-se a pena em dobro se o crime é praticado por ascendente, parente consanguíneo até terceiro grau, responsável legal, tutor, guardião, padrasto ou madrasta da vítima.', '["Omissão de comunicação à autoridade: detenção de seis meses a três anos.","Aumento de metade se resultar lesão grave e pena triplicada se resultar morte.","Pena em dobro para ascendente, parente até terceiro grau, responsável, tutor, guardião, padrasto ou madrasta."]'::jsonb, '["Crime de omissão: pune quem não comunica.","Pena triplicada se resultar morte."]'::jsonb, 'Quem sabe das agressões e não comunica a ninguém responde pelo crime do art. 26.', '["Assertiva que aplica a pena de reclusão ao art. 26 erra: é detenção."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-26'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fica instituído, em todo o território nacional, o dia 3 de maio de cada ano como Dia Nacional de Combate à Violência Doméstica e Familiar contra a Criança e o Adolescente, em homenagem ao menino Henry Borel.', '["Dia Nacional de Combate à Violência Doméstica e Familiar contra a Criança e o Adolescente.","Comemorado em 3 de maio.","Homenagem a Henry Borel."]'::jsonb, '["Data: 3 de maio."]'::jsonb, 'Em 3 de maio ocorrem campanhas sobre a violência contra crianças.', '["Assertiva que fixa o dia nacional em outra data erra: é 3 de maio."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-27'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 4º da Lei nº 13.431, de 4 de abril de 2017, passa a ter um inciso V, que inclui a violência patrimonial, entendida como qualquer conduta que configure retenção, subtração, destruição parcial ou total de documentos pessoais, bens, valores e direitos ou recursos econômicos da criança ou do adolescente, desde que a medida não se enquadre como educacional.', '["Acrescenta a violência patrimonial à Lei nº 13.431.","Retenção, subtração ou destruição de documentos, bens e valores."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei nº 13.431, de 4 de abril de 2017."]'::jsonb, 'Reter os documentos da criança para controlá-la é violência patrimonial.', '["Assertiva que exclui a violência patrimonial das formas de violência contra a criança erra."]'::jsonb, '[]'::jsonb, '["Lei nº 13.431"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-28'
