insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O parágrafo único do art. 152 da Lei de Execução Penal passa a prever que, nos casos de violência doméstica e familiar contra a criança, o adolescente e a mulher e de tratamento cruel ou degradante, ou de uso de formas violentas de educação, correção ou disciplina contra a criança e o adolescente, o juiz poderá determinar o comparecimento obrigatório do agressor a programas de recuperação e reeducação.', '["Comparecimento obrigatório do agressor a programas de recuperação e reeducação.","Vale para violência contra criança, adolescente e mulher."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei de Execução Penal."]'::jsonb, 'O juiz determina que o agressor frequente programa de reeducação.', '["Assertiva que limita o comparecimento a programas à violência contra a mulher erra: inclui criança e adolescente."]'::jsonb, '[]'::jsonb, '["Lei de Execução Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-30'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo altera o Código Penal: no art. 111, a prescrição, nos crimes contra a dignidade sexual ou que envolvam violência contra a criança e o adolescente, só começa a correr da data em que a vítima completar 18 anos, salvo se já houver ação penal proposta; no art. 121, cria a qualificadora do homicídio contra menor de 14 anos e prevê aumento de 1/3 até a metade se a vítima for pessoa com deficiência ou doença que aumente sua vulnerabilidade, e de 2/3 se o autor for ascendente, padrasto, madrasta, tio, irmão, cônjuge, companheiro, tutor, curador, preceptor ou empregador; amplia a causa de aumento do §7º para vítima maior de 60 anos, com deficiência ou doenças degenerativas; e, no art. 141, o aumento dos crimes contra a honra quando a vítima for criança, adolescente, maior de 60 anos ou pessoa com deficiência.', '["Prescrição só corre após a vítima completar 18 anos (crimes sexuais e de violência contra criança).","Homicídio contra menor de 14 anos: qualificadora.","Aumento de 1/3 até a metade (vítima vulnerável) e de 2/3 (autor com autoridade).","Aumento nos crimes contra a honra contra vulneráveis."]'::jsonb, '["ATUALIZAÇÃO: altera o Código Penal; confira a redação vigente.","Marco inicial da prescrição: 18 anos da vítima."]'::jsonb, 'O prazo de prescrição do crime contra criança só começa quando ela completa 18 anos.', '["Assertiva que fixa a prescrição desde a data do fato nesses crimes erra: começa aos 18 anos da vítima, salvo ação penal já proposta."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-31'
