insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O inciso I do art. 1º da Lei dos Crimes Hediondos passa a abranger o homicídio quando praticado em atividade típica de grupo de extermínio, ainda que cometido por um só agente, e o homicídio qualificado, incluindo o homicídio contra menor de 14 anos (inciso IX do §2º do art. 121 do Código Penal).', '["Homicídio qualificado, inclusive contra menor de 14 anos, é hediondo.","Homicídio de grupo de extermínio também."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei dos Crimes Hediondos."]'::jsonb, 'O homicídio qualificado de uma criança de dez anos é crime hediondo.', '["Assertiva que exclui o homicídio contra menor de 14 anos do rol dos hediondos erra."]'::jsonb, '[]'::jsonb, '["Lei dos Crimes Hediondos"]'::jsonb, 'under_review', 'claude'
